effect.shader:
float hash(vec2 p) {
p = fract(p * vec2(123.34, 456.21));
p += dot(p, p + 45.32);
return fract(p.x * p.y);
}
float noise(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
float a = hash(i + vec2(0.0, 0.0));
float b = hash(i + vec2(1.0, 0.0));
float c = hash(i + vec2(0.0, 1.0));
float d = hash(i + vec2(1.0, 1.0));
return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
float total = 0.0;
float amp = 0.5;
mat2 rot = mat2(0.877582, 0.479426, -0.479426, 0.877582);
for (int i = 0; i < 6; i++) {
total += noise(p) * amp;
p = rot * p * 2.0 + 100.0;
amp *= 0.5;
}
return total;
}
void main() {
vec2 uv = acLayerNorm.xy - 0.5;
uv.x *= acLayerSize.x / acLayerSize.y;
float t = acTime * speed + seed;
vec2 q = vec2(0.0);
q.x = fbm(uv + vec2(0.0, 0.0) + 0.05 * t);
q.y = fbm(uv + vec2(5.2, 1.3) + 0.05 * t);
vec2 r = vec2(0.0);
r.x = fbm(uv + 4.0 * q + vec2(1.7, 9.2) + 0.15 * t);
r.y = fbm(uv + 4.0 * q + vec2(8.3, 2.8) + 0.126 * t);
float f = fbm(uv + 4.0 * r);
float dist = length(uv);
float inkShape = (expansion * 0.3) - dist + (f - 0.5) * (roughness * 0.2);
float safeBleed = max(bleed, 0.001);
float mask = smoothstep(-safeBleed, 0.0, inkShape);
vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
if (alphaMode) {
gl_FragColor = vec4(texColor.rgb, texColor.a * mask);
} else {
vec3 finalCol = mix(paperColor.rgb, inkColor.rgb, mask);
gl_FragColor = vec4(finalCol, 1.0);
}
}
